function countByExtension(names) {
  const counts = {};
  for (const name of names) {
    const dot = name.lastIndexOf(".");
    const ext = dot > 0 ? name.slice(dot) : "(none)";
    counts[ext] = (counts[ext] ?? 0) + 1;
  }
  return counts;
}

const names = ["today.txt", "todo.txt", "plan.md", "report.final.pdf", "README"];
const counts = countByExtension(names);
console.log(JSON.stringify(counts, Object.keys(counts).sort()));

