questions.solution:
function loadOrDefault(read, fallback) {
  try {
    return read();
  } catch (error) {
    if (error.code === "ENOENT") return fallback;
    throw error;
  }
}

function failWith(code) {
  return () => {
    const error = new Error(`failed with ${code}`);
    error.code = code;
    throw error;
  };
}

console.log(loadOrDefault(() => "saved tasks", "no tasks"));
console.log(loadOrDefault(failWith("ENOENT"), "no tasks"));
try {
  loadOrDefault(failWith("EACCES"), "no tasks");
  console.log("error was hidden");
} catch (error) {
  console.log("re-thrown:", error.code);
}

